#!/usr/bin/env python3
"""Reproduce the reviewed drift classification and pinned source-line mapping."""
from pathlib import Path
import collections,difflib,json,re,subprocess
ROOT=Path(__file__).resolve().parents[4]; OUT=Path(__file__).resolve().parent
OLD='0aa0a5224804f1d2a2fb0be0cea79e8f599736bc'; NEW='4c1854202a8e109479d5b83ef24a8325231da056'
cache={}
def src(path,sha=NEW):
 key=(path,sha)
 if key not in cache:cache[key]=subprocess.check_output(['git','-C',str(ROOT),'show',sha+':'+path],text=True).splitlines()
 return cache[key]
def link(path,line,end=None):
 assert 1<=line<=len(src(path)); assert not end or end<=len(src(path))
 return f'[{path}:{line}](https://github.com/ethanwongwork/area/blob/{NEW}/{path}#L{line}'+(f'-L{end}' if end else '')+')'
def at(path,text):return next(i for i,l in enumerate(src(path),1) if text in l)
def ref(path,text,end=0):
 n=at(path,text);return link(path,n,n+end if end else None)
def remap(path,line):
 a,b=src(path,OLD),src(path)
 for op,x,y,u,v in difflib.SequenceMatcher(None,a,b,autojunk=False).get_opcodes():
  if x<=line-1<y:return min(len(b),u+(line-1-x if op=='equal' else 0)+1)
 raise ValueError((path,line))
def plain(s):return re.sub(r'\[([^]]*)\]\([^)]*\)',r'\1',s)
prior=(OUT/'2026-10-02.md').read_text(); rows=[]
for line in prior.splitlines():
 if not re.match(r'\| D\d\d ',line):continue
 cells=re.split(r' \| ',line.strip('| ')); title=cells[0]; id=title[:3]
 refs=[]
 for path,n in dict.fromkeys(re.findall(r'https://github.com/ethanwongwork/area/blob/'+OLD+r'/([^#)]+)#L(\d+)',line)):
  current=remap(path,int(n));refs.append({'path':path,'old_line':int(n),'line':current})
 status='changed' if id in ['D08','D10'] else 'fixed' if id=='D23' else 'still open'
 explanation=plain(cells[-1]).replace('Owner proposal:', 'Recommendation:')
 if id=='D08':explanation='The former ignored-pill mismatch is superseded: Badge now supports true / false / unset and the page documents all three. However, the current spec still excludes rounded badges as pill-only. Reconcile the spec with the restored override; do not restore the old deprecated-prop advice.'
 if id=='D10':explanation='The old ignored-pill mismatch is superseded: Chip now implements the override and the page documents unset/true/false. Its current Decisions still prescribe radius-full without the theme/override qualification. Update the shape contract, not the restored prop.'
 if id=='D23':explanation='Fixed for the originally cited default sm swatch: even-pixel rounding maps 16 × 0.2 to 4, and the ColorField concentric cap preserves 4 at the default setting. The old 3.2-versus-4 discrepancy no longer holds. Other radius settings intentionally vary; this is not a claim that all swatches always have radius 4.'
 def current_text(cell):
  def replace(m):
   path,old_line=m.group(1),int(m.group(2));current=remap(path,old_line)
   return link(path,current,min(len(src(path)),current+3))
  return re.sub(r'\[[^]]*\]\(https://github.com/ethanwongwork/area/blob/'+OLD+r'/([^#)]+)#L(\d+)(?:-L\d+)?\)',replace,cell)
 comparison=[current_text(cells[i]) for i in (1,4,5)] if status=='still open' else []
 rows.append(dict(id=id,title=title,status=status,explanation=explanation,comparison=comparison,refs=refs))
assert [r['id'] for r in rows]==[f'D{i:02}' for i in range(1,41)]
counts=collections.Counter(r['status'] for r in rows)
new=[]
def add(id,title,text,refs):new.append(dict(id=id,title=title,text=text,refs=[ref(*r) for r in refs]))
add('N01','Tag picker — old Badge contract survives the Tag replacement','The implementation imports Tag and exposes TagTone, including gray/brown/pink; the page still calls option tone a Badge tone, while the spec anatomy, size row and Decisions still name Badge. The later feedback records the replacement, so these current contract sections should be reconciled.', [('packages/react/src/components/TagPicker.tsx','import { Tag'),('packages/react/src/components/TagPicker.tsx','tone?: TagTone'),('apps/docs/src/pages.mjs','tone is a Badge tone'),('docs/specs/tag-picker.md','| tag | Badge'),('docs/specs/tag-picker.md','instead of Badge')])
add('N02','Tag picker — conditional hint documented as unconditional','Without onCreate, the default heading is Select tags; with onCreate it is Select a tag or create one. The page gives only the latter as the default. Document both branches.', [('packages/react/src/components/TagPicker.tsx','const hintText'),('apps/docs/src/pages.mjs','hint null hides it')])
add('N03','Tag and corner setting — Sharp remove plate stays rounded','The Tag shell goes square at radius 0, but the remove control floors its corner at the fixed space-2. This contradicts the corner setting’s square-everywhere contract. Derivation: max(2px, 0px − 2px) = 2px. Recommend using the radius floor or another Sharp-aware nested recipe after owner review.', [('packages/styles/src/components/tag.css','border-radius: max(var(--area-space-2)'),('packages/styles/src/components/tag.css','border-radius: max(var(--area-radius-min)'),('packages/tokens/src/axes/radius.ts','Sharp: square corners everywhere'),('packages/tokens/src/emit/base.ts','radius-floor')])
add('N04','Disclosure — current inset equation retains pre-change spacing','The current Anatomy/inset equations still say divided trigger/content padding 16 (compact 12); the corrected Decisions and CSS now use 10 (compact 8). The historical 2026-10-02 Visual pass can stay dated, but the live equation needs updating.', [('docs/specs/disclosure.md','- divided: trigger padding-block 16',1),('docs/specs/disclosure.md','| divided · trigger |'),('packages/styles/src/components/disclosure.css','--_trigger-pad: calc(10px'),('packages/styles/src/components/disclosure.css','--_content-end: calc(10px')])
add('N05','Card — current corner table predates the new setting','The current Decisions table still gives 22/24/28 and a Button-plus-text-column formula. Current CSS derives the corner from radius-container plus the inset term: at default radius 8 and default density, surface 12 plus 2/4/8 gives 14/16/20 for sm/md/lg. Compact is 10/12/14. Update the formula and default table; do not change the new corner behavior to match stale prose.', [('docs/specs/card.md','| radius / inset |'),('packages/styles/src/components/surface.css','--_card-radius:',7),('packages/styles/src/components/surface.css','.area-card--sm',12),('packages/tokens/src/axes/radius.ts','["8", 8, 12]'),('packages/tokens/src/emit/base.ts','radius-floor')])
add('N06','Alignment picker — removed size and stretch still in spec','React keeps size/stretch only as ignored compatibility inputs; the manifest has neither size nor stretch and CSS fills its parent. The spec Variants still offers sm/md/lg and stretch, and current inset equations still prescribe an 80px square. Update those contract sections to the responsive model recorded later in the feedback.', [('docs/specs/alignment-picker.md','| size |'),('docs/specs/alignment-picker.md','Inset equation:',1),('packages/react/src/components/AlignmentPicker.tsx','@deprecated The picker fills',3),('packages/styles/src/manifest.ts','export const alignmentPicker',10)])
add('N07','Date picker — calendar locale/week-start default differs from page','The page says browser locale and locale-derived week start. DatePicker passes possibly-undefined locale and firstDayOfWeek into Calendar, whose defaults are en-US and Sunday (0). Its outer date label uses Intl with the possibly-undefined locale, so an implicit non-US browser locale can disagree with the calendar. Recommend one documented locale/week-start policy and an explicit propagation decision.', [('apps/docs/src/pages.mjs','"the clock / the browser / locale"'),('packages/react/src/components/DatePicker.tsx','const format ='),('packages/react/src/components/DatePicker.tsx','locale={locale} firstDayOfWeek'),('packages/react/src/components/Calendar.tsx','firstDayOfWeek = 0')])
add('N08','Tag — compact dimensions absent from current contract','Spec and page give sm 20 / md 24 and a 16px remove box without density qualification. CSS reads mark-label-md/lg, which become 16/20 in compact; the remove box becomes 12/16. This is documentation drift, not evidence that compact scaling is wrong. Document the compact mapping explicitly.', [('docs/specs/tag.md','| size |'),('docs/specs/tag.md','| × |'),('packages/styles/src/components/tag.css','--_height: var(--area-mark-label-md)'),('packages/styles/src/components/tag.css','--_remove: calc'),('packages/styles/src/components/tag.css','.area-tag--md'),('packages/tokens/src/axes/density.ts','export const COMPACT_ROLES'),('apps/docs/src/pages.mjs','"sm" (20)')])
lines=['# Component contract drift — 2026-10-07','','**Question:** Which of the 40 earlier drift findings are fixed, still open or changed on latest fetched main, and what new drift appears in the added/changed component contracts?','','**Answer:**',f'- Of the original 40: **{counts["fixed"]} fixed, {counts["still open"]} still open, {counts["changed"]} changed**. Every original ID is retained below.','- The default ColorField swatch radius now agrees; Badge and Chip pill findings changed because the prop became functional again.',f'- **{len(new)} new findings** cover Tag/Tag picker, Disclosure, Card/corner setting, Alignment picker and DatePicker.','- Recommended: reconcile current contract tables with the implementation and later owner decisions; the Tag remove plate at Sharp and DatePicker locale split also warrant implementation review. No fixes or approvals were made.','',f'**Snapshot:** `origin/main` `{NEW}`, fetched 2026-10-07 (America/Los_Angeles). Baseline `{OLD}` from [2026-10-02.md](2026-10-02.md). All current Area source links are pinned to the new snapshot.','','## Scope and method','','“Fixed” means the original concrete discrepancy no longer exists. “Still open” means the conflicting current contract remains. “Changed” means an intentional implementation change invalidated the old diagnosis but left a different contract discrepancy. These are static source findings, not browser verdicts. Historical captures and dated feedback are not treated as current-value promises.','','Re-read all 40 cited contracts; map original locations through Git line diffs and inspect replacement source. The added/changed-family pass covers Tag, Tag picker, Custom select, Date picker, Drawer, Confirm dialog, Disclosure, Alignment picker and the corner-setting consumers implicated below. This is a targeted extension, not a claim to exhaustively re-audit the icon library or every line of all changed files.','','## Earlier findings, in original ID order','']
for r in rows:
 lines += [f'### {r["title"]} — {r["status"]}','',r['explanation'],'','Current pinned evidence: '+ '; '.join(link(x['path'],x['line'],min(len(src(x['path'])),x['line']+3)) for x in r['refs'])+'.','']
 if r['comparison']: lines += ['Current comparison: '+ ' **·** '.join(f'**{label}:** {value}' for label,value in zip(['CSS / tokens','Spec','Page / demo'],r['comparison'])), '']
 if r['id']=='D08':lines += ['Restored behavior: '+ref('packages/react/src/components/Badge.tsx','Unset: a pill',2)+'; '+ref('apps/docs/src/pages.mjs','["pill", "boolean; unset follows',1)+'.','']
 if r['id']=='D10':lines += ['Restored behavior: '+ref('packages/react/src/components/primitives.tsx','rounded: pill === false')+'; current spec: '+ref('docs/specs/chip.md','| radius | pill')+'.','']
 if r['id']=='D23':lines += ['New rule and embedded-field cap: '+ref('packages/styles/src/components/color.css','--_radius: max',3)+'; '+ref('packages/styles/src/components/color.css','.area-color-field .area-input__icon > .area-color-swatch',4)+'.','']
lines += ['## New mismatches','']
for r in new:lines += [f'### {r["id"]} — {r["title"]}','',r['text'],'','Evidence: '+'; '.join(r['refs'])+'.','']
lines += ['## Checked without another finding','','Custom select’s outline/soft/ghost and size axes agree across spec, manifest and page; Drawer’s added row/stacked actions and modal option are represented; ConfirmDialog’s neutral/danger button composition is represented. These bounded checks do not certify behavior or clear their Unverified notes. '+ref('packages/styles/src/manifest.ts','export const customSelect',8)+'; '+ref('docs/specs/custom-select.md','| variant |',3)+'; '+ref('docs/specs/drawer.md','| layout |',1)+'; '+ref('packages/react/src/components/Drawer.tsx','modal?:')+'; '+ref('packages/react/src/components/ConfirmDialog.tsx','<Button variant={tone')+'.','','## Proposals','','1. Refresh the current spec Decisions/Variants/Anatomy and page API together, retaining dated feedback as history.','2. Review the two source-behavior findings (N03 Sharp Tag remove plate; N07 locale propagation) before editing CSS/React.','3. Keep D08/D10 linked to their former diagnosis so a follow-up never deprecates the newly restored prop by mistake.','','## Open questions','','- Should DatePicker infer week start from locale, or explicitly default to Sunday? The current page and Calendar disagree.','- Should Tag’s compact size mapping become an explicit spec row, or remain inherited with a density note?','- Do owners want an automated docs/API value checker for the repeated enum/count drift?','','## Reproduce and verification','','Run `python3 docs/research/astra/drift/recheck.py` from the repository root. The script locates the root relative to itself, reads pinned Git objects and the prior report, and regenerates this dated file plus its evidence JSON. Classifications and new findings are reviewed judgments embedded in the script; it does not claim to infer drift automatically.','','Checks: all D01–D40 IDs appear once, every cited current line exists, and the dated baseline is left unchanged. Report-only: no build/runtime certification or owner status change.','']
(OUT/'2026-10-07.md').write_text('\n'.join(lines)); (OUT/'2026-10-07.json').write_text(json.dumps({'baseline':OLD,'snapshot':NEW,'previous':rows,'new':new},indent=2)+'\n')
print(dict(counts),'new',len(new))
